from __future__ import annotations

def invariants(a: float, b: float, c: float, d: float) -> tuple[float, float]:
    return a*d-b*c, a*a+b*b+c*c+d*d

if __name__ == "__main__":
    base = (1.0, 2.0, -1.0, 3.0)
    det0, energy0 = invariants(*base)
    for r in (0.5, 1.0, 2.0, 4.0):
        scaled = tuple(r*x for x in base)
        det, energy = invariants(*scaled)
        print(f"r={r:g}: det ratio={det/det0:g}, energy ratio={energy/energy0:g}, expected={r*r:g}")


# Integer-window companion
from itertools import product

def count(radius: int, lower: float, upper: float) -> int:
    total = 0
    for a, b, c, d in product(range(-radius, radius + 1), repeat=4):
        if a*a+b*b+c*c+d*d < radius*radius and lower < a*d-b*c < upper:
            total += 1
    return total

if __name__ == "__main__":
    for radius in range(2, 8):
        print(radius, count(radius, 1/3, 2/3))

